public enum State
{
    Idle,
    Move,
    Attack,
    Hit
}

State state = State.Idle;

state = State.Attack;
if (state == State.Attack) { }

void Update()
{
    switch (state)
    {
        case State.Idle:
            UpdateIdle();
            break;
        case State.Move:
            UpdateMove();
            break;
        case State.Attack:
            UpdateAttack();
            break;
    }
}

switch (state)
{
    case State.Idle:
        UpdateIdle();
        break;  // 꼭 필요

    // 어느 case에도 안 맞으면
    default:
        Debug.Log("모르는 상태");
        break;
}

void ChangeState(State next)
{
    if (state == next) return;

    state = next;

    if (next == State.Attack)
        anim.SetTrigger("Attack");
    else if (next == State.Hit)
        StartCoroutine(Blink());
}

void UpdateIdle()
{
    float dist = Vector3.Distance(transform.position, player.position);
    if (dist < 5f)
        ChangeState(State.Move);
}

void UpdateMove()
{
    // 플레이어 쪽으로 이동...
    float dist = Vector3.Distance(transform.position, player.position);
    if (dist < 1.5f)
        ChangeState(State.Attack);
}

